const __aivicBundle_19_sendDailyReportAndNotify = (() => {
  async function sendDailyReportAndNotify(params: {
    user_id: string;
    email_address: string;
    user_name: string;
    yesterday_work: string;
    today_plan: string;
    current_issue: string;
    submission_datetime: string;
  }): Promise<{ report_id: string; status: string }> {
    const {
      user_id,
      email_address,
      user_name,
      yesterday_work,
      today_plan,
      current_issue,
      submission_datetime,
    } = params;
  
    if (!email_address) {
      throw new Error('送信者のメールアドレスが登録されていません');
    }
  
    const reportId = `report_${new Date(submission_datetime).toISOString().split('T')[0].replace(/-/g, '')}_${user_id}`;
  
    const emailSubject = `朝会報告: ${user_name}`;
    const emailBody = `
  昨日の成果:
  ${yesterday_work}
  
  今日の予定:
  ${today_plan}
  
  現在の課題:
  ${current_issue}
  `;
  
    const mailPayload = {
      recipient: email_address,
      subject: emailSubject,
      body: emailBody,
    };
  
    const response = await fetch('/api/send-mail', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(mailPayload),
    });
  
    if (!response.ok) {
      const statusText = response.status.toString();
      throw new Error(`メール送信に失敗しました: ${statusText}`);
    }
  
    return {
      report_id: reportId,
      status: 'sent',
    };
  }
  return { sendDailyReportAndNotify };
})();
